diff --git a/rust/fsl-core/tests/reviewgraphen_generated_calibration_03.rs b/rust/fsl-core/tests/reviewgraphen_generated_calibration_03.rs
new file mode 100644
--- /dev/null
+++ b/rust/fsl-core/tests/reviewgraphen_generated_calibration_03.rs
@@ -0,0 +1,32 @@
+// SPDX-License-Identifier: Apache-2.0
+
+use fsl_core::{FsResolver, build_model, parse_kernel_source};
+
+#[test]
+fn reviewgraphen_generated_regression() {
+    let source = r#"domain EnumShadowing {
+  type Status enum { ready, done }
+
+  aggregate Ticket {
+    state {
+      status: Status
+    }
+
+    command choose(ready: Bool)
+    event chosen
+
+    decide choose {
+      emits chosen
+    }
+
+    evolve chosen {
+      status = ready
+    }
+  }
+}
+"#;
+    let kernel = parse_kernel_source(source, &FsResolver::new(".")).expect("lower domain");
+    build_model(kernel).expect_err(
+        "the Bool command parameter must not be rewritten as the same-named Status member",
+    );
+}
